package org.sahamati.iopgw.gateway;

/** An error generated by this gateway, with its status, errorCode and errorMsg. */
public final class GwError extends Exception {
    public final int status;
    public final String code;
    /** Set on internal API errors raised after a hop answered: the hop that delivered it. */
    public final String forwardingHop;

    public GwError(int status, String code, String msg) {
        this(status, code, msg, null);
    }

    public GwError(int status, String code, String msg, String forwardingHop) {
        super(msg, null, false, false);
        this.status = status;
        this.code = code;
        this.forwardingHop = forwardingHop;
    }

    public static final String INVALID_URI = "InvalidURI";
    public static final String INVALID_REQUEST = "InvalidRequest";
    public static final String INVALID_ROUTE = "InvalidRoute";
    public static final String INVALID_SECURITY = "InvalidSecurity";
    public static final String SIG_MISMATCH = "SignatureDoesNotMatch";
    public static final String DOWNSTREAM = "IopDownstreamError";
    public static final String INTERNAL = "InternalError";
    public static final String BAD_GATEWAY = "BadGateway";
    public static final String GATEWAY_TIMEOUT = "GatewayTimeout";
    public static final String ALL_ROUTES = "AllRoutesUnavailable";
}
